    text_l = text.lower()
    scores = {k: 0 for k in SUBJECTS}
    for subject, keywords in KEYWORDS.items():
        for kw in keywords:
            if " " in kw:
                if kw in text_l:
                    scores[subject] += 5
            else:
                # word boundary count
                scores[subject] += len(re.findall(rf"\b{re.escape(kw)}\b", text_l))
    return scores


def filename_hint(name: str, scores: dict) -> dict:
    fn = name.lower()
    for subject, keywords in KEYWORDS.items():
        for kw in keywords:
            if kw.replace(" ", "_") in fn or kw in fn:
                scores[subject] += 2
    return scores


files = [p for p in ROOT.iterdir() if p.is_file()]
rows = []
for path in files:
    text = extract_text(path)
    scores = score_text(text)
    scores = filename_hint(path.name, scores)
    # Choose max score
    best = sorted(scores.items(), key=lambda x: (-x[1], x[0]))[0][0]
    max_score = scores[best]
    total = sum(scores.values())
